0\",\"wfwundefined-0-na\",{\"href\":\"/en/search/synonyms/?original=na\",\"children\":[\"$\",\"em\",null,{\"children\":\"na\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"nor\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-5\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-śaśāṅkaḥ\",{\"href\":\"/en/search/synonyms/?original=śaśāṅkaḥ\",\"children\":[\"$\",\"em\",null,{\"children\":\"śaśāṅkaḥ\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"the moon\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-6\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-na\",{\"href\":\"/en/search/synonyms/?original=na\",\"children\":[\"$\",\"em\",null,{\"children\":\"na\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"nor\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-7\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-pāvakaḥ\",{\"href\":\"/en/search/synonyms/?original=pāvakaḥ\",\"children\":[\"$\",\"em\",null,{\"children\":\"pāvakaḥ\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"fire, electricity\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-8\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-yat\",{\"href\":\"/en/search/synonyms/?original=yat\",\"children\":[\"$\",\"em\",null,{\"children\":\"yat\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"where\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-9\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-gatvā\",{\"href\":\"/en/search/synonyms/?original=gatvā\",\"children\":[\"$\",\"em\",null,{\"children\":\"gatvā\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"going\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-10\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-na\",{\"href\":\"/en/search/synonyms/?original=na\",\"children\":[\"$\",\"em\",null,{\"children\":\"na\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"never\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-11\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-nivartante\",{\"href\":\"/en/search/synonyms/?original=nivartante\",\"children\":[\"$\",\"em\",null,{\"children\":\"nivartante\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"they come back\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-12\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-tat\",{\"href\":\"/en/search/synonyms/?original=tat\",\"children\":[\"$\",\"em\",null,{\"children\":\"tat\"}]}],\" \",[\"$\",\"$L20\",\"wfwundefined-2-dhāma\",{\"href\":\"/en/search/synonyms/?original=dhāma\",\"children\":[\"$\",\"em\",null,{\"children\":\"dhāma\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"that abode\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-13\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-paramam\",{\"href\":\"/en/search/synonyms/?original=paramam\",\"children\":[\"$\",\"em\",null,{\"children\":\"paramam\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"supreme\"}}],\"; \"]}],\"$L32\"]}]}]]]}]\n"])self.__next_f.push([1,"2e:[\"$\",\"div\",\"4015-translation,4015-translation\",{\"className\":\"av-translation\",\"children\":[[\"$\",\"h2\",null,{\"className\":\"text-center em-leading-5 em-text-xl font-bold em-mb-4\",\"children\":\"Translation\"}],[[\"$\",\"$L2a\",\"child-4019\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:3:children:0\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"children\":[\"$\",\"strong\",null,{\"dangerouslySetInnerHTML\":{\"__html\":\"That supreme abode of Mine is not illumined by the sun or moon, nor by fire or electricity. Those who reach it never return to this material world.\"}}]}]}]]]}]\n33:T47c,One should be captivated by this information. He should desire to transfer himself to that eternal world and extricate himself from this false reflection of reality. For one who is too much attached to this material world, it is very difficult to cut that attachment, but if he takes to Kṛṣṇa consciousness there is a chance of gradually becoming detached. One has to associate himself with devotees, those who are in Kṛṣṇa consciousness. One should search out a society dedicated to Kṛṣṇa consciousness and learn how to discharge devotional service. In this way he can cut off his attachment to the material world. One cannot become detached from the attraction of the material world simply by dressing himself in saffron cloth. He must become attached to the devotional service of the Lord. Therefore one should take it very seriously that devotional service as described in the Twelfth Chapter is the only way to get out of this false representation of the real tree. In Chapter Fourteen the contamination of all kinds of processes by material nature is described. Only devotional service is described as purely transcendental."])self.__next_f.push([1,"2f:[\"$\",\"div\",\"4015-purport,4015-purport\",{\"className\":\"av-purport\",\"children\":[[\"$\",\"h2\",null,{\"className\":\"text-center em-leading-5 em-text-xl font-bold em-mb-4\",\"children\":\"Purport\"}],[[\"$\",\"$L2a\",\"child-4020\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:0\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"The spiritual world, the abode of the Supreme Personality of Godhead, Kṛṣṇa – which is known as Kṛṣṇaloka, Goloka Vṛndāvana – is described here. In the spiritual sky there is no need of sunshine, moonshine, fire or electricity, because all the planets are self-luminous. We have only one planet in this universe, the sun, which is self-luminous, but all the planets in the spiritual sky are self-luminous. The shining effulgence of all those planets (called Vaikuṇṭhas) constitutes the shining sky known as the brahma-jyotir. Actually, the effulgence is emanating from the planet of Kṛṣṇa, Goloka Vṛndāvana. Part of that shining effulgence is covered by the mahat-tattva, the material world. Other than this, the major portion of that shining sky is full of spiritual planets, which are called Vaikuṇṭhas, chief of which is Goloka Vṛndāvana.\"}}]}],[\"$\",\"$L2a\",\"child-4021\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:1\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"As long as a living entity is in this dark material world, he is in conditional life, but as soon as he reaches the spiritual sky by cutting through the false, perverted tree of this material world, he becomes liberated. Then there is no chance of his coming back here. In his conditional life, the living entity considers himself to be the lord of this material world, but in his liberated state he enters into the spiritual kingdom and becomes an associate of the Supreme Lord. There he enjoys eternal bliss, eternal life, and full knowledge.\"}}]}],[\"$\",\"$L2a\",\"child-4022\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:2\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"$33\"}}]}],[\"$\",\"$L2a\",\"child-4023\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:3\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"The words paramaṁ mama are very important here. Actually every nook and corner is the property of the Supreme Lord, but the spiritual world is paramam, full of six opulences. The Kaṭha Upaniṣad (2.2.15) also confirms that in the spiritual world there is no need of sunshine, moonshine or stars (na tatra sūryo bhāti na candra-tārakam), for the whole spiritual sky is illuminated by the internal potency of the Supreme Lord. That supreme abode can be achieved only by surrender and by no other means.\"}}]}]]]}]\n"])self.__next_f.push([1,"34:[[\"$\",\"source\",null,{\"srcSet\":\"https://simpleanalyticsbadges.com/vedabase.io?mode=auto\",\"media\":\"(prefers-color-scheme: dark)\"}],[\"$\",\"img\",null,{\"src\":\"https://simpleanalyticsbadges.com/vedabase.io?mode=auto\",\"loading\":\"lazy\",\"referrerPolicy\":\"no-referrer\",\"crossOrigin\":\"anonymous\"}]]\n"])self.__next_f.push([1,"27:[\"$\",\"div\",null,{\"id\":\"footer\",\"className\":\"mt-auto w-full max-w-7xl mx-auto pt-3 mb-6 text-sm text-vb-normal-text/80 text-center\",\"children\":[[\"$\",\"$L1f\",null,{\"donors\":\"Shweta Saxena; Gopalakrishnan Soundarajan;    Kuldip Persaud;  Raghava Chandra Dasa; Shubhangi Rajiv Panjiyar; Suparna Kotaru;  Rajendra and Geeta Ramchandani;  Jaykumar Prabhakar; Bharat Vyas; Shri Chander Mohan Gilhotra, HG Prashant Mukund Das, Shri Trilok Singh Grover, HG Bhakta Mitra Das, Laxmi Narayan Agarwal; Ronak Talati; Bhargav Ashok; Akiralali; Rajasa das; Riya and Tejal Chopade; Indradyumna Swami; Jai Devaki Parks;  Ashmi Chakraborty; Hari-kirtana das; Ramesta das; Prasad Buddhavarapu; Kresna Sucandra; Esekiel Jaggernauth\",\"locale\":\"en\"}],[\"$\",\"div\",null,{\"className\":\"w-full max-w-screen-xl mx-auto text-vb-normal-text mb-3\",\"children\":[[\"$\",\"a\",null,{\"target\":\"_blank\",\"rel\":\"noopener noreferrer\",\"h